package com.smartmart.order.service; import com.smartmart.common.exception.*; import com.smartmart.inventory.repository.InventoryRepository; import com.smartmart.order.dto.*; import com.smartmart.order.entity.*; import com.smartmart.order.repository.*; import com.smartmart.product.entity.Product; import com.smartmart.product.repository.ProductRepository; import com.smartmart.user.entity.User; import lombok.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.math.*; import java.util.*;
@Service @RequiredArgsConstructor public class OrderService{private final CartItemRepository carts;private final CustomerOrderRepository orders;private final ProductRepository products;private final InventoryRepository inventory;private final com.smartmart.user.repository.UserRepository users;@org.springframework.beans.factory.annotation.Value("${smartmart.delivery.fee:50.00}") private BigDecimal deliveryFee=new BigDecimal("50.00");
 @Transactional public CartResponse add(User u,CartRequest r){Product p=products.findById(r.getProductId()).orElseThrow(()->BusinessException.notFound("Product not found"));var inv=inventory.findByProductId(p.getId()).orElseThrow(()->BusinessException.badRequest("Product is unavailable: "+p.getName()));int requested=r.getQuantity();int already=carts.findByUserIdAndProductId(u.getId(),r.getProductId()).map(CartItem::getQuantity).orElse(0);if(requested<1)throw BusinessException.badRequest("Quantity must be at least 1");if(already+requested>inv.getQuantity())throw BusinessException.badRequest("Only "+inv.getQuantity()+" units of "+p.getName()+" are currently available.");CartItem c=carts.findByUserIdAndProductId(u.getId(),r.getProductId()).orElse(CartItem.builder().user(u).product(p).quantity(0).build());c.setQuantity(already+requested);carts.save(c);return cart(u);}@Transactional public CartResponse update(User u,Long p,int q){if(q<1){remove(u,p);return cart(u);}CartItem c=carts.findByUserIdAndProductId(u.getId(),p).orElseThrow(()->BusinessException.notFound("Cart item not found"));var inv=inventory.findByProductId(p).orElseThrow(()->BusinessException.badRequest("Product is unavailable: "+c.getProduct().getName()));if(q>inv.getQuantity())throw BusinessException.badRequest("Only "+inv.getQuantity()+" units of "+c.getProduct().getName()+" are currently available.");c.setQuantity(q);return cart(u);}@Transactional public void remove(User u,Long p){carts.deleteByUserIdAndProductId(u.getId(),p);}@Transactional(readOnly=true) public CartResponse cart(User u){List<CartResponse.Item> list=carts.findByUserId(u.getId()).stream().map(c->{var inv=inventory.findByProductId(c.getProduct().getId()).orElse(null);BigDecimal price=discounted(c.getProduct(),inv);return CartResponse.Item.builder().productId(c.getProduct().getId()).name(c.getProduct().getName()).quantity(c.getQuantity()).available(inv==null?0:inv.getQuantity()).unitPrice(price).subtotal(price.multiply(BigDecimal.valueOf(c.getQuantity()))).build();}).toList();BigDecimal subtotal=list.stream().map(CartResponse.Item::getSubtotal).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal fee=deliveryFeeAmount();return CartResponse.builder().items(list).total(subtotal).deliveryFee(fee).totalPayable(subtotal.add(fee)).build();}
 @Transactional public OrderResponse checkout(User u,DeliveryDetailsRequest details){if(details==null)throw BusinessException.badRequest("Delivery details are required");BigDecimal fee=deliveryFeeAmount();String mobile=details.mobileNumber().replaceAll("[\\s()\\-]", "");String digits=mobile.replaceAll("\\D", "");if(digits.length()<10||digits.length()>15)throw BusinessException.badRequest("Enter a valid mobile number");String name=details.fullName().trim(),address=details.address().trim(),city=details.city().trim(),pin=details.pinCode().trim();if(name.isEmpty()||address.isEmpty()||city.isEmpty()||!pin.matches("[0-9]{6}"))throw BusinessException.badRequest("Complete all required delivery details");List<CartItem> lines=carts.findByUserId(u.getId());if(lines.isEmpty())throw BusinessException.badRequest("Cart is empty");CustomerOrder o=CustomerOrder.builder().user(u).deliveryName(name).deliveryMobile(mobile).deliveryAddress(address).deliveryCity(city).deliveryPinCode(pin).deliveryInstructions(details.deliveryInstructions()==null||details.deliveryInstructions().isBlank()?null:details.deliveryInstructions().trim()).status(OrderStatus.CONFIRMED).deliveryStatus(DeliveryStatus.PLACED).paymentStatus(PaymentStatus.PENDING).deliveryFee(fee).totalAmount(BigDecimal.ZERO).items(new ArrayList<>()).build();BigDecimal subtotal=BigDecimal.ZERO;for(CartItem c:lines){var inv=inventory.findByProductId(c.getProduct().getId()).orElseThrow(()->BusinessException.badRequest("Product is unavailable: "+c.getProduct().getName()));if(inv.getExpiryDate()!=null&&inv.getExpiryDate().isBefore(java.time.LocalDate.now()))throw BusinessException.badRequest("Product has expired: "+c.getProduct().getName());if(inv.getQuantity()<c.getQuantity())throw BusinessException.badRequest("Insufficient inventory for "+c.getProduct().getName());BigDecimal price=discounted(c.getProduct(),inv), sub=price.multiply(BigDecimal.valueOf(c.getQuantity()));inv.setQuantity(inv.getQuantity()-c.getQuantity());OrderItem item=OrderItem.builder().order(o).product(c.getProduct()).quantity(c.getQuantity()).unitPrice(price).subtotal(sub).build();o.getItems().add(item);subtotal=subtotal.add(sub);}o.setSubtotalAmount(subtotal);o.setTotalAmount(subtotal.add(fee));var profile=users.findById(u.getId()).orElseThrow();profile.setName(name);profile.setMobileNumber(mobile);profile.setDeliveryAddress(address);profile.setDeliveryCity(city);profile.setDeliveryPinCode(pin);profile.setDeliveryInstructions(o.getDeliveryInstructions());users.save(profile);CustomerOrder saved=orders.save(o);carts.deleteByUserId(u.getId());return map(saved);}
 @Transactional(readOnly=true) public List<OrderResponse> history(User u){return orders.findByUserIdOrderByCreatedAtDesc(u.getId()).stream().map(this::map).toList();}@Transactional(readOnly=true) public OrderResponse find(User u,Long id,boolean manager){CustomerOrder o=orders.findWithItemsById(id).orElseThrow(()->BusinessException.notFound("Order not found"));if(!manager&&!o.getUser().getId().equals(u.getId()))throw BusinessException.forbidden("This order belongs to another user");return map(o);}@Transactional(readOnly=true) public List<OrderResponse> all(){return orders.findAllWithItems().stream().map(this::map).toList();}
 @Transactional public OrderResponse updateDeliveryStatus(Long id,DeliveryStatus next){CustomerOrder order=orders.findWithItemsById(id).orElseThrow(()->BusinessException.notFound("Order not found"));DeliveryStatus current=order.getDeliveryStatus();if(current==null||order.getStatus()==OrderStatus.CANCELLED||next==null||current==DeliveryStatus.DELIVERED||next.ordinal()!=current.ordinal()+1)throw BusinessException.conflict("Invalid delivery status transition");order.setDeliveryStatus(next);return map(order);}
 private BigDecimal deliveryFeeAmount(){if(deliveryFee==null||deliveryFee.signum()<0)throw new IllegalStateException("smartmart.delivery.fee must be zero or greater");return deliveryFee.setScale(2,java.math.RoundingMode.HALF_UP);} private BigDecimal discounted(Product p,com.smartmart.inventory.entity.Inventory i){if(i==null||i.getDiscountPercentage()==null)return p.getPrice();return p.getPrice().multiply(BigDecimal.ONE.subtract(i.getDiscountPercentage().movePointLeft(2))).setScale(2,java.math.RoundingMode.HALF_UP);} private OrderResponse map(CustomerOrder o){OrderResponse.Delivery delivery=o.getDeliveryName()==null?null:OrderResponse.Delivery.builder().fullName(o.getDeliveryName()).mobileNumber(o.getDeliveryMobile()).address(o.getDeliveryAddress()).city(o.getDeliveryCity()).pinCode(o.getDeliveryPinCode()).deliveryInstructions(o.getDeliveryInstructions()).build();return OrderResponse.builder().id(o.getId()).userId(o.getUser().getId()).customerName(o.getUser().getName()).delivery(delivery).subtotalAmount(o.getSubtotalAmount()).deliveryFee(o.getDeliveryFee()).totalAmount(o.getTotalAmount()).status(o.getStatus()).deliveryStatus(o.getDeliveryStatus()).paymentStatus(o.getPaymentStatus()==null?PaymentStatus.PENDING:o.getPaymentStatus()).createdAt(o.getCreatedAt()).items(o.getItems().stream().map(i->OrderResponse.Item.builder().productId(i.getProduct().getId()).productName(i.getProduct().getName()).quantity(i.getQuantity()).unitPrice(i.getUnitPrice()).subtotal(i.getSubtotal()).build()).toList()).build();}}
